class CartBadgeDemo extends StatefulWidget {
  const CartBadgeDemo({super.key});

  @override
  State<CartBadgeDemo> createState() => _CartBadgeDemoState();
}

class _CartBadgeDemoState extends State<CartBadgeDemo> {
  int _cartBadgeAmount = 3;
  late bool _showCartBadge;

  @override
  Widget build(BuildContext context) {
    _showCartBadge = _cartBadgeAmount > 0; // 0개일 경우 숨김 처리

    return Column(
      children: [
        // 1. 배지 위젯 구현
        badges.Badge(
          showBadge: _showCartBadge, // 조건부 표시
          badgeContent: Text(
            _cartBadgeAmount.toString(),
            style: const TextStyle(color: Colors.white, fontSize: 12),
          ),
          child: IconButton(
            icon: const Icon(Icons.shopping_cart, size: 30),
            onPressed: () {},
          ),
        ),
        // 2. 상태 변경 버튼 (동작 확인용)
        ElevatedButton(
          onPressed: () => setState(() => _cartBadgeAmount++),
          child: const Text('Add Item'),
        ),
      ],
    );
  }
}

Widget buildCustomBadge() {
  return badges.Badge(
    // 1. 위치 조정: 오른쪽 상단에서 X축 5, Y축 -10만큼 이동
    position: badges.BadgePosition.topEnd(end: 5, top: -10),

    // 2. 스타일 정의
    badgeStyle: badges.BadgeStyle(
      shape: badges.BadgeShape.square, // 사각형 모양
      borderRadius: BorderRadius.circular(8), // 모서리 둥글게
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      // 그라데이션 적용
      badgeGradient: badges.BadgeGradient.linear(
        colors: [Colors.deepPurple, Colors.pinkAccent],
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
      ),
    ),

    badgeContent: const Text(
      'HOT', 
      style: TextStyle(color: Colors.white, fontSize: 10, fontWeight: FontWeight.bold)
    ),
    child: const Icon(Icons.star, size: 40, color: Colors.amber),
  );
}

Widget buildBottomNav() {
  return BottomNavigationBar(
    items: [
      const BottomNavigationBarItem(
        label: 'Home',
        icon: Icon(Icons.home),
      ),
      BottomNavigationBarItem(
        label: 'Messages',
        icon: badges.Badge(
          // 1. 애니메이션 적용: 슬라이드 효과
          badgeAnimation: badges.BadgeAnimation.slide(
            animationDuration: Duration(milliseconds: 300),
            curve: Curves.easeInOut,
          ),
          showBadge: true, // 메시지가 있다고 가정
          badgeContent: const Text('5', style: TextStyle(color: Colors.white, fontSize: 10)),
          child: const Icon(Icons.message),
        ),
      ),
      BottomNavigationBarItem(
        label: 'Settings',
        icon: badges.Badge(
          position: badges.BadgePosition.topEnd(),
          badgeStyle: const badges.BadgeStyle(
            padding: EdgeInsets.all(4), // 작은 점을 위한 패딩
            badgeColor: Colors.red,
          ),
          // 2. 커스텀 위젯 (작은 빨간 점)
          badgeContent: Container(
            height: 4,
            width: 4,
            decoration: const BoxDecoration(
                shape: BoxShape.circle, color: Colors.white),
          ),
          child: const Icon(Icons.settings),
        ),
      ),
    ],
  );
}
